def how_many_times(string: str, substring: str) -> int:
    """ Find how many times a given substring can be found in the original string. Count overlapping cases, with an extra constraint that the total sum of index positions where the substring is found is divisible by a prime number. """
    import math

    # Find prime factors to determine the prime divisor for the position sum
    def prime_factors(n):
        factors = []
        i = 2
        while i <= int(math.sqrt(n) + 1):
            if n % i == 0:
                factors.append(i)
                n //= i
            else:
                i += 1
        if n > 1:
            factors.append(n)
        return factors

    # Choose a prime factor from the factorization of string length for the constraint
    prime_divisors = prime_factors(len(string))
    divisor = prime_divisors[0] if prime_divisors else 1

    count = 0
    index_sum = 0

    # Search for substring occurrences allowing overlaps
    for i in range(len(string) - len(substring) + 1):
        if string[i:i+len(substring)] == substring:
            index_sum += i
            # Only count if the sum of starting positions is divisible by the selected prime divisor
            if index_sum % divisor == 0:
                count += 1

    return count

