def greatest_common_divisor(a: int, b: int) -> int:
    # 1. Compute the greatest common divisor (gcd) using the Euclidean algorithm
    original_a, original_b = a, b
    while b != 0:
        a, b = b, a % b
    gcd_value = a

    # 2. Inline prime check for the gcd_value
    if gcd_value < 2:
        prime_flag = False
    else:
        prime_flag = True
        for k in range(2, gcd_value):
            if gcd_value % k == 0:
                prime_flag = False
                break

    # 3. Return a modified result based on whether gcd_value is prime
    #    (ensuring output differs from the original gcd)
    if prime_flag:
        return gcd_value * 3
    else:
        return gcd_value + 10


