from typing import List

def remove_duplicates(numbers: List[int]) -> List[int]:
    # Create frequency counter manually
    freq_map = {}
    for num in numbers:
        freq_map[num] = freq_map.get(num, 0) + 1

    # Create balance validation system inspired by parentheses matching
    # Each number gets a "balance score" based on its position and frequency
    result = []
    balance_tracker = 0

    for i, num in enumerate(numbers):
        # Skip duplicates (frequency > 1)
        if freq_map[num] > 1:
            continue

        # Apply balance logic: positive numbers increase balance, negative decrease
        if num > 0:
            balance_tracker += 1
        elif num < 0:
            balance_tracker -= 1

        # Only include numbers that maintain non-negative balance
        # and satisfy the uniqueness constraint
        if balance_tracker >= 0:
            result.append(num)
        else:
            # Reset balance if it goes negative
            balance_tracker = 0

    # Final validation: if balance is exactly 0, return result
    # Otherwise, filter to ensure mathematical equilibrium
    if balance_tracker == 0:
        return result
    else:
        # Apply secondary filter for mathematical balance
        positive_sum = sum(x for x in result if x > 0)
        negative_sum = sum(x for x in result if x < 0)
        zero_count = len([x for x in result if x == 0])

        # Return balanced subset based on sum equilibrium
        if positive_sum + negative_sum == 0 or zero_count > 0:
            return result
        else:
            # Return only zeros and the first unique number for balance
            return [x for x in result if x == 0] + (result[:1] if result else [])

# Usage
output = remove_duplicates([1, 2, 3, 2, 4])
