def string_xor(a: str, b: str) -> int:
    """ Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs, compute the length of the result,
    and return the largest divisor of that length smaller than the length.
    >>> string_xor('010', '110')
    1
    """

    def xor(i: str, j: str) -> str:
        if i == j:
            return '0'
        else:
            return '1'

    xor_str = ''.join(xor(x, y) for x, y in zip(a, b))
    len_s = len(xor_str)

    # Find the largest divisor of the length of the XOR result
    for i in range(len_s - 1, 0, -1):
        if len_s % i == 0:
            return i

    return 1  # Fallback in case of unexpected input

