def encode(message):
    """
    Encodes a message by swapping case, replacing vowels with letters two places ahead,
    and applying a bitwise XOR with 1 to all consonants.
    """
    vowels = "aeiouAEIOU"
    vowels_replace = {i: chr(ord(i) + 2) for i in vowels}
    message = message.swapcase()
    result = []
    for char in message:
        if char in vowels:
            result.append(vowels_replace[char])
        else:
            result.append(chr(ord(char) ^ 1))
    return ''.join(result)

