def minPath(grid, k):
    """
    Modified version of the basic problem's minPath function. 
    Returns a tuple containing the path, the sum of its elements, and the product of its elements.
    """
    n = len(grid)
    val = n * n + 1

    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                temp = []
                if i != 0:
                    temp.append(grid[i - 1][j])
                if j != 0:
                    temp.append(grid[i][j - 1])
                if i != n - 1:
                    temp.append(grid[i + 1][j])
                if j != n - 1:
                    temp.append(grid[i][j + 1])
                val = min(temp)

    ans = []
    for i in range(k):
        if i % 2 == 0:
            ans.append(1)
        else:
            ans.append(val)

    sum_val = sum(ans)
    product_val = 1
    for num in ans:
        product_val *= num

    return (ans, sum_val, product_val)

