def right_angle_triangle(a, b, c):
    '''
    Given the lengths of the three sides of a triangle. Return the sum of the sides if they form a right-angled triangle, 
    otherwise return 0. Additionally, if any side is a float, it is rounded using the closest_integer logic before checking.
    '''
    # Convert inputs to float and round using closest_integer logic if necessary
    def round_value(val):
        if isinstance(val, float):
            from math import floor, ceil
            if val == int(val):
                return int(val)
            if val - int(val) == 0.5:
                return ceil(val) if val > 0 else floor(val)
            else:
                return round(val)
        return val

    a_r = round_value(a)
    b_r = round_value(b)
    c_r = round_value(c)

    # Check for right-angled triangle condition
    if a_r**2 == b_r**2 + c_r**2 or b_r**2 == a_r**2 + c_r**2 or c_r**2 == a_r**2 + b_r**2:
        return a_r + b_r + c_r
    else:
        return 0

