def triangle_area(a, h):
    """Generate a grid of size a x a with values from 1 to a², then find the minimum path of length h using a specific logic."""
    # Generate grid of size a x a filled with numbers from 1 to a²
    grid = [[i * a + j + 1 for j in range(a)] for i in range(a)]
    n = a
    val = n * n + 1
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                temp = []
                if i != 0:
                    temp.append(grid[i - 1][j])
                if j != 0:
                    temp.append(grid[i][j - 1])
                if i != n - 1:
                    temp.append(grid[i + 1][j])
                if j != n - 1:
                    temp.append(grid[i][j + 1])
                val = min(temp)
    ans = []
    for i in range(h):
        if i % 2 == 0:
            ans.append(1)
        else:
            ans.append(val)
    return ans

