code:
def count_distinct_characters(string: str) -> dict:
    """ Given a string, find out how many distinct characters (regardless of case) it consists of,
    and also check if the brackets in the string are correctly balanced.
    Returns a dictionary with the distinct character count and a boolean for bracket correctness.
    >>> count_distinct_characters('xyzXYZ')
    {'distinct_chars': 3, 'brackets_correct': None}
    >>> count_distinct_characters('Jerry')
    {'distinct_chars': 4, 'brackets_correct': None}
    >>> count_distinct_characters('(aBc)')
    {'distinct_chars': 4, 'brackets_correct': True}
    """

    # 1. Calculate distinct characters (case-insensitive)
    lower_string = string.lower()
    distinct_characters = set(lower_string)
    char_count = len(distinct_characters)

    # 2. Check for bracket correctness
    brackets = [c for c in string if c in '()']
    bracket_result = None
    if brackets:
        depth = 0
        for b in brackets:
            if b == "(":
                depth += 1
            else:
                depth -= 1
            if depth < 0:
                bracket_result = False
                break
        if bracket_result is None:
            bracket_result = (depth == 0)

    return {'distinct_chars': char_count, 'brackets_correct': bracket_result}

