from typing import List, Dict, Union
import math

def has_close_elements(numbers: List[float], threshold: float) -> Dict[str, Union[float, List[float], bool]]:
    """Enhanced function that checks for close elements and returns detailed analysis.
    Returns a dictionary containing:
    - 'result': boolean indicating if close elements exist
    - 'closest_pair': the closest pair found (empty if none)
    - 'min_distance': the minimum distance found (infinity if none)
    - 'is_prime_count': whether the count of close pairs is prime

    >>> has_close_elements([1.0, 2.0, 3.0], 0.5)
    {'result': False, 'closest_pair': [], 'min_distance': 1.0, 'is_prime_count': False}
    >>> has_close_elements([1.0, 2.8, 3.0, 4.0, 5.0, 2.0], 0.3)
    {'result': True, 'closest_pair': [2.8, 3.0], 'min_distance': 0.2, 'is_prime_count': True}
    """

    min_distance = math.inf
    closest_pair = []
    close_pairs_count = 0

    for idx, elem in enumerate(numbers):
        for idx2, elem2 in enumerate(numbers):
            if idx != idx2:
                distance = abs(elem - elem2)
                if distance < min_distance:
                    min_distance = distance
                    closest_pair = [min(elem, elem2), max(elem, elem2)]
                if distance < threshold:
                    close_pairs_count += 1

    # Check if close_pairs_count is prime (using logic from x_or_y)
    is_prime = True
    if close_pairs_count <= 1:
        is_prime = False
    else:
        for i in range(2, int(math.sqrt(close_pairs_count)) + 1):
            if close_pairs_count % i == 0:
                is_prime = False
                break

    return {
        'result': min_distance < threshold,
        'closest_pair': closest_pair if min_distance < threshold else [],
        'min_distance': min_distance,
        'is_prime_count': is_prime
    }

