from typing import List

def rolling_max(numbers: List[int]) -> List[str]:
    """Enhanced rolling maximum with case-swapping and reversal logic.
    Returns a list where:
    - If current number is even: append current max as uppercase string
    - If odd: append as lowercase string
    - If empty input: returns reversed list of string representations
    - If all numbers are zero: returns reversed list
    """
    if not numbers:
        return [str(num) for num in numbers[::-1]]

    if all(num == 0 for num in numbers):
        return [str(num) for num in numbers[::-1]]

    running_max = None
    result = []
    has_non_zero = False

    for n in numbers:
        if running_max is None:
            running_max = n
        else:
            running_max = max(running_max, n)

        if n != 0:
            has_non_zero = True

        if running_max % 2 == 0:
            result.append(str(running_max).upper())
        else:
            result.append(str(running_max).lower())

    if not has_non_zero:
        return result[::-1]

    return result

