def smallest_change(arr):
    """
    Given an array arr of integers, find the minimum number of elements that
    need to be changed to make the array palindromic, while also considering
    the product of odd digits in the elements that need to be changed.
    Returns a tuple containing (changes_needed, product_of_odd_digits_in_changes).
    If no changes are needed, returns (0, 1).

    For example:
    smallest_change([1,2,3,5,4,7,9,6]) == (4, 945)
    smallest_change([1, 2, 3, 4, 3, 2, 2]) == (1, 3)
    smallest_change([1, 2, 3, 2, 1]) == (0, 1)
    """

    changes = 0
    product = 1
    odd_count = 0

    for i in range(len(arr) // 2):
        left = arr[i]
        right = arr[len(arr) - i - 1]

        if left != right:
            changes += 1
            # Calculate product of odd digits in both elements
            for num in [left, right]:
                for digit in str(abs(num)):
                    int_digit = int(digit)
                    if int_digit % 2 == 1:
                        product *= int_digit
                        odd_count += 1

    if changes == 0:
        return (0, 1)
    if odd_count == 0:
        return (changes, 0)
    return (changes, product)

