def sort_array(arr):
    """
    Enhanced version that sorts based on:
    1. Number of ones in binary representation (ascending)
    2. For equal ones, sorts by decimal value (ascending)
    3. For negative numbers, uses two's complement representation
    4. Includes a mango fruit calculation twist for positive numbers
    """

    def count_ones(x):
        if x >= 0:
            return bin(x).count('1')
        else:
            # Two's complement for negative numbers
            return bin(x & 0xFFFFFFFF).count('1')

    def mango_calc(x):
        if x > 0:
            # Using the fruit distribution logic for positive numbers
            fake_fruit_str = f"{x} apples and {x//2} oranges"
            total_fruits = x * 3
            return total_fruits - x - (x//2)
        return 0

    # Primary sort by binary ones count
    arr_sorted = sorted(arr, key=lambda x: (count_ones(x), x))

    # Secondary processing with mango calculation for positive numbers
    result = []
    for num in arr_sorted:
        if num > 0:
            result.append(mango_calc(num))
        else:
            result.append(num)

    return result

