def get_closest_vowel(word):
    """Enhanced version that finds the closest vowel between consonants from the right,
    and also counts prime hexadecimal digits in the vowel's ASCII code.

    Returns a tuple containing:
    1. The closest vowel (or empty string if none found)
    2. The count of prime digits in the vowel's ASCII hex representation
    Example:
    get_closest_vowel("yogurt") ==> ("u", 0)  # 'u' ASCII 117 (0x75) has 0 prime digits
    get_closest_vowel("FULL") ==> ("U", 1)    # 'U' ASCII 85 (0x55) has 1 prime digit (5)
    """
    # Original vowel finding logic
    if len(word) < 3:
        return ("", 0)

    vowels = {"a", "e", "i", "o", "u", "A", "E", 'O', 'U', 'I'}
    primes = {'2', '3', '5', '7', 'B', 'D'}

    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels:
            if (word[i + 1] not in vowels) and (word[i - 1] not in vowels):
                # New: Count prime digits in the vowel's ASCII hex
                hex_code = hex(ord(word[i]))[2:].upper()
                prime_count = sum(1 for d in hex_code if d in primes)
                return (word[i], prime_count)

    return ("", 0)

