def valid_date(date):
    """Validates a date string and returns a list of [month, day, year] if valid, otherwise an empty list.
    The date is valid if:
    1. The date string is not empty.
    2. The format is mm-dd-yyyy.
    3. The month is between 1 and 12.
    4. The day is valid for the given month, including leap year checks for February.
    5. The year is a non-negative integer.
    """

    try:
        date = date.strip()
        parts = date.split('-')
        if len(parts) != 3:
            return []

        month_str, day_str, year_str = parts
        month = int(month_str)
        day = int(day_str)
        year = int(year_str)

        if not (1 <= month <= 12):
            return []

        if year < 0:
            return []

        # Determine max days based on month and leap year for February
        if month in [1, 3, 5, 7, 8, 10, 12]:
            max_day = 31
        elif month in [4, 6, 9, 11]:
            max_day = 30
        elif month == 2:
            # Leap year check
            if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
                max_day = 29
            else:
                max_day = 28
        else:
            return []

        if not (1 <= day <= max_day):
            return []

        return [month, day, year]

    except:
        return []

