def same_chars(s0: str, s1: str):
    """
    Check if two words have the same characters and return a dictionary with the count of each character.
    >>> same_chars('eabcdzzzz', 'dddzzzzzzzddeddabc')
    {'a': 1, 'b': 1, 'c': 1, 'd': 5, 'e': 2, 'z': 4}
    >>> same_chars('abcd', 'dddddddabc')
    {'a': 1, 'b': 1, 'c': 1, 'd': 7}
    >>> same_chars('dddddddabc', 'abcd')
    {'a': 1, 'b': 1, 'c': 1, 'd': 7}
    >>> same_chars('eabcd', 'dddddddabc')
    {}
    >>> same_chars('abcd', 'dddddddabce')
    {}
    >>> same_chars('eabcdzzzz', 'dddzzzzzzzddddabc')
    {}
    """

    # 1. Convert both strings to sets to check if they have the same characters
    if set(s0) != set(s1):
        return {}

    # 2. Create a dictionary to store the count of each character
    char_count = {}

    # 3. Count the characters in both strings and store the minimum count for each character
    for char in set(s0):
        char_count[char] = min(s0.count(char), s1.count(char))

    return char_count

